def f(g):
    g=[r[:] for r in g]; H,W=len(g),len(g[0])
    cnt=Counter(v for row in g for v in row if v!=0)
    sqc=[c for c,n in cnt.items() if n>=4][0]
    def nearest(i,j,sqcells):
        return min(sqcells,key=lambda p:abs(p[0]-i)+abs(p[1]-j))
    sq=[(i,j) for i in range(H) for j in range(W) if g[i][j]==sqc]
    singles=[(i,j,g[i][j]) for i in range(H) for j in range(W) if g[i][j]!=0 and g[i][j]!=sqc]
    # group markers by nearest square
    groups={}
    for i,j,c in singles:
        s=nearest(i,j,sq); key=s; groups.setdefault(key,[]).append((i,j,c))
    out=[r[:] for r in g]
    for s,ms in groups.items():
        rows=[i for i,_ in s]; cols=[j for _,j in s]
        sr=(min(rows)+max(rows))/2; sc=(min(cols)+max(cols))/2
        # quadrant spots relative to square
        spots={'TL':(min(rows),min(cols)),'TR':(min(rows),max(cols)),'BL':(max(rows),min(cols)),'BR':(max(rows),max(cols))}
        q={'TL' if i<sr else 'BL'}[i<sround(0)] if False else None
        qmap={}
        for i,j,c in ms:
            q='T' if i<sr else 'B'; q+= 'L' if j<sc else 'R'
            qmap[(i,j)]=q
        # CW shift: TL->TR, TR->BR, BR->BL, BL->TL
        newpos={}
        for (i,j),q in qmap.items():
            target=qmap.get(None,None)
            if q=='TL': tq='TR'
            elif q=='TR': tq='BR'
            elif q=='BR': tq='BL'
            else: tq='TL'
            tp=spots[tq]
            if tp not in sq and (tp not in newpos or True):
                newpos[(i,j)]=tp
            else:
                newpos[(i,j)]=(i,j)  # blocked: stay
        # paint shifts
        for (i,j) in list(newpos):
            tp=newpos[(i,j)]; c=g[i][j]
            out[tp[0]][tp[1]]=c
            del out[i][j] if out[i][j]==c else None
        # rays: away from nearest square cell
        for (i,j) in list(newpos):
            c=out[i][j]; sp=spots[qmap[(i,j)]]  # old quad
            if (i,j) in sq: continue
            near=nearest(i,j,sq)
            dr=1 if i>near[0] else -1 if i<near[0] else 0
            dc=1 if j>near[1] else -1 if j<near[1] else 0
            x,y=i+dr,j+dc
            while 0<=x<H and 0<=y<W and out[x][y]==0:
                out[x][y]=c; x+=dr; y+=dc
    return out
