from collections import defaultdict, Counter
def rays(I,O,var='all'):
    H,W=len(I),len(I[0])
    twos={(i,j) for i in range(H) for j in range(W) if I[i][j]==2}
    seeds=[(i,j,I[i][j]) for i in range(H) for j in range(W) if I[i][j] not in (0,2)]
    def blocked(y,x): return not(0<=y<H and 0<=x<W) or (y,x) in twos
    # precompute clear runs from each seed in each diag dir (length until first block)
    runs=[]
    for i,j,c in seeds:
        for name,(d1,d2) in [('ne',(1,1)),('sw',(-1,1)),('nw',(-1,-1)),('se',(1,-1))]:
            y,x=i+d1,j+d2; n=0
            while not blocked(y,x): y+=d1; x+=d2; n+=1
            runs.append((n,name,i,j,c))
    # conflict resolution variants
    def f(win):
        O2=[[0]*W for _ in range(H)]
        for i in range(H):
            for j in range(W):
                if I[i][j]!=0 and I[i][j]!=2: continue
                best=None
                for n,name,s_i,s_j,c in runs:
                    yi=s_i+(1 if 'e' in name else -1)*0  # dummy
                # redo: for each cell find which rays cover it
                pass
        # simpler: paint each ray fully (cells until block), later rays overwrite
        O2=[[0]*W for _ in range(H)]
        order=[]
        for s in sorted(seeds):
            order.append(s)
        segs=[]
        for i,j,c in seeds:
            for name,(d1,d2) in [('ne',(1,1)),('sw',(-1,1)),('nw',(-1,-1)),('se',(1,-1))]:
                y,x=i+d1,j+d2; seg=[]
                while 0<=y<H and 0<=x<W and (y,x) not in twos:
                    if O2[y][x]==0: seg.append((y,x))
                    else: break
                    y+=d1; x+=d2
                segs.append((seg,name,i,j,c))
        for seg,name,s_i,s_j,c in segs:
            if win=='last':
                for (y,x) in seg: O2[y][x]=c
            elif win=='first':
                for (y,x) in seg: O2[y][x]=c
        return O2
    res={}
    for win in ('first','last'):
        S=f(win)
        miss=sum(1 for i in range(H) for j in range(W) if S[i][j]!=O[i][j])
        res[(win,var)]=miss
    return res
